function selectCampaigns(campaigns, maxSpend) {
  // Helper: insert id into a sorted copy of an array
  function insertSorted(arr, val) {
    const res = arr.slice();
    let i = 0;
    while (i < res.length && res[i] < val) i++;
    res.splice(i, 0, val);
    return res;
  }

  // Helper: compare two states according to the tie‑breaking rules
  function isBetter(a, b) {
    if (a.signups !== b.signups) return a.signups > b.signups;
    if (a.spend !== b.spend) return a.spend < b.spend;
    const aStr = a.ids.join(',');
    const bStr = b.ids.join(',');
    return aStr < bStr;
  }

  // DP array: dp[spend] = best state achieving exactly that spend
  const dp = new Array(maxSpend + 1).fill(null);
  dp[0] = { signups: 0, ids: [], spend: 0 };

  for (const camp of campaigns) {
    const w = Math.floor(camp.dailySpend); // assume integer spend
    const v = camp.expectedSignups;
    const id = camp.id;

    for (let s = maxSpend; s >= w; s--) {
      const prev = dp[s - w];
      if (!prev) continue;

      const candSignups = prev.signups + v;
      const candIds = insertSorted(prev.ids, id);
      const candState = { signups: candSignups, ids: candIds, spend: s };

      const existing = dp[s];
      if (!existing || isBetter(candState, existing)) {
        dp[s] = candState;
      }
    }
  }

  // Find the overall best state among all feasible spends
  let best = null;
  for (let s = 0; s <= maxSpend; s++) {
    const state = dp[s];
    if (!state) continue;
    if (!best || isBetter(state, best)) best = state;
  }

  return best ? best.ids : [];
}

